#define main legacy_probe_main
#include "diagnose_token_write.cpp"
#undef main
#include <set>
#include <sstream>
#include <fstream>
std::string key(const Seq&s){std::ostringstream out;out<<s.query<<":";for(int t:s.tokens)out<<t<<",";return out.str();}
int main(int argc,char**argv){try{unsigned seed=argc>1?std::stoul(argv[1]):42;std::string optimizer=argc>2?argv[2]:"adam";Net net(seed);std::mt19937 data_rng(58191),order(12345);std::vector<Seq>train;std::set<std::string>seen;while(train.size()<512){auto s=make(data_rng,data_rng()%3);if(seen.insert(key(s)).second)train.push_back(s);}W gradient{},m{},v{};int steps=optimizer=="adam"?3000:1200;for(int step=1;step<=steps;++step){gradient.fill(0);int batch=optimizer=="adam"?32:512;for(int j=0;j<batch;++j)net.run(train[optimizer=="adam"?order()%train.size():j],&gradient);for(int i=0;i<N;++i){double g=gradient[i]/batch+.0001*net.w[i];if(optimizer=="adam"){m[i]=.9*m[i]+.1*g;v[i]=.999*v[i]+.001*g*g;net.w[i]-=.003*(m[i]/(1-std::pow(.9,step)))/(std::sqrt(v[i]/(1-std::pow(.999,step)))+1e-8);}else net.w[i]-=.15*g;}}double tr=0;int tok=0;for(auto&s:train){int a;tr+=net.run(s,nullptr,nullptr,&a);tok+=a==s.target;}printf("seed=%u optimizer=%s trainhard=%.6f CE=%.9f\n",seed,optimizer.c_str(),tok/512.,tr/512);for(int noise:{0,2,8,32,128}){std::mt19937 test(28181+noise);std::set<std::string>unique;int n=0,softok=0,hardok=0,overlap=0;double ce=0;int wanted=noise==0?128:256;while(n<wanted){auto s=make(test,noise);auto k=key(s);if(seen.count(k)){++overlap;continue;}if(!unique.insert(k).second)continue;int a,b;ce+=net.run(s,nullptr,&a,&b);softok+=a==s.target;hardok+=b==s.target;++n;}printf("noise=%d n=%d soft=%.6f hard=%.6f CE=%.9f rejected_train_overlap=%d\n",noise,n,double(softok)/n,double(hardok)/n,ce/n,overlap);}std::ofstream out("build/token_write_"+optimizer+"_"+std::to_string(seed)+".weights",std::ios::binary);out.write((char*)net.w.data(),sizeof(net.w));if(!out)throw std::runtime_error("write weights");return 0;}catch(const std::exception&e){fprintf(stderr,"FAIL %s\n",e.what());return 1;}}
